/**
 * ENG-834: describe_image returned 400 INVALID_ARGUMENT on 4K images generated by
 * gemini-3.1-flash-image when the configured vision model is a Gemini model
 * (prod uses gemini-3.5-flash).
 *
 * Root cause: describeImage only downloaded + normalized + downscaled the image
 * (inlining it as a base64 data URI) for `anthropic.*` / `claude-*` vision models.
 * For Gemini models the raw S3 URL was passed straight through, so the Gemini
 * native client sent it as `fileData.fileUri`. Gemini fetches such URLs fine for
 * ordinary screenshots, but rejects the un-downscaled 4K image (3072x5504, ~16MB)
 * with 400 INVALID_ARGUMENT. Prod evidence: that oversize class failed on Gemini
 * in 100% of the sessions that attempted it (2026-06-11 through 2026-08-02), while
 * sub-MB images on the identical code path succeeded — so size, not URL fetching,
 * is the discriminator.
 *
 * Why it only became user-visible in August: before the native Gemini adapter
 * (ENG-737, 2026-07-30) the error read "400 status code (no body)", which
 * isRetryableMediaToolError() classifies as retryable, so the Claude vision
 * fallback silently rescued every occurrence. The native adapter surfaces
 * Google's raw "...INVALID_ARGUMENT" JSON, which trips that method's /invalid/i
 * non-retryable pattern — so the fallback stopped firing and the failure went hard.
 *
 * Fix: download + normalize + downscale-and-inline for the Gemini path too, so
 * the vision call always receives a small, self-contained data URI.
 *
 * sharp is real here so the >4MB downscale path is exercised end-to-end.
 */

jest.mock('aws-sdk', () => ({
  DynamoDB: {
    DocumentClient: jest.fn(() => ({
      put: jest.fn().mockReturnValue({ promise: jest.fn().mockResolvedValue({}) }),
      get: jest.fn().mockReturnValue({ promise: jest.fn().mockResolvedValue({}) }),
      scan: jest.fn().mockReturnValue({ promise: jest.fn().mockResolvedValue({}) }),
      query: jest.fn().mockReturnValue({ promise: jest.fn().mockResolvedValue({}) }),
      update: jest.fn().mockReturnValue({ promise: jest.fn().mockResolvedValue({}) }),
      delete: jest.fn().mockReturnValue({ promise: jest.fn().mockResolvedValue({}) }),
    })),
  },
  S3: jest.fn(() => ({})),
  SecretsManager: jest.fn(() => ({})),
  config: { update: jest.fn() },
}));

const mockAxiosGet = jest.fn();
// Keep REAL axios (transitive imports rely on axios.create/interceptors at load
// time) and override only .get for the image download.
jest.mock('axios', () => {
  const actual = jest.requireActual('axios');
  const get = (...a: any[]) => mockAxiosGet(...a);
  return {
    __esModule: true,
    ...actual,
    get,
    default: Object.assign(actual.default.create(), { get }),
  };
});

jest.mock('../utils/s3Utils', () => ({
  isS3Url: jest.fn().mockReturnValue(true),
  presignS3Url: jest.fn((u: string) => `${u}?presigned=1`),
}));

// describe_image is agent-callable and fed URLs from untrusted content, so the
// non-S3 fetch path must go through the repo's SSRF-guarded fetch rather than a
// bare axios.get. Mock that helper to avoid real DNS/network and assert the
// delegation; its hop-by-hop guard semantics are covered exhaustively in
// ssrfGuard.fetchBufferFollowingRedirects.test.ts.
const mockGuardedFetch = jest.fn();
jest.mock('../utils/ssrfGuard', () => {
  const actual = jest.requireActual('../utils/ssrfGuard');
  return {
    ...actual,
    fetchBufferFollowingRedirects: (...a: any[]) => mockGuardedFetch(...a),
  };
});

jest.mock('../services/chatbotService');
jest.mock('../services/settingsService');
jest.mock('../utils/secretsManager');

import sharp from 'sharp';
import { randomBytes } from 'crypto';
import { AgentModeService } from '../services/agentModeService';
import { isS3Url } from '../utils/s3Utils';
import { SsrfBlockedError } from '../utils/ssrfGuard';

const S3_URL =
  'https://agentweb-user-files.s3.us-west-2.amazonaws.com/users/x/files/1/y/cover.png';

describe('describeImage — Gemini vision path inlines + downscales (ENG-834)', () => {
  let service: AgentModeService;

  beforeEach(() => {
    jest.clearAllMocks();
    service = new AgentModeService();
  });

  it('downloads and inlines the image as a data URI for a Gemini vision model (never the raw S3 URL)', async () => {
    // Minimal valid 1x1 PNG.
    const pngBytes = Buffer.from(
      'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==',
      'base64'
    );
    mockAxiosGet.mockResolvedValue({ data: pngBytes, headers: { 'content-type': 'image/png' } });
    const callLLMSpy = jest
      .spyOn(service, 'callLLM')
      .mockResolvedValue({ choices: [{ message: { content: 'a cover image' } }] } as any);

    const result = await service.describeImage('gemini-3.5-flash', S3_URL);

    expect(result.success).toBe(true);
    expect(mockAxiosGet).toHaveBeenCalled();
    expect(callLLMSpy).toHaveBeenCalled();
    const [, messages] = callLLMSpy.mock.calls[0];
    const imgBlock = (messages[0].content as any[]).find((c: any) => c.type === 'image_url');
    // Must be inlined bytes — NOT the bare S3 URL Gemini's fileData.fileUri cannot fetch.
    expect(imgBlock.image_url.url).toMatch(/^data:image\//);
    expect(imgBlock.image_url.url).not.toContain('s3.us-west-2.amazonaws.com');
  });

  it('downscales an oversized 4K image to a JPEG data URI under the 4MB inline limit', async () => {
    // Build a genuinely >4MB PNG (random noise is incompressible) to mirror the
    // reported 4K gemini-3.1-flash-image output.
    const width = 2048;
    const height = 2048;
    const raw = randomBytes(width * height * 3);
    const bigPng = await sharp(raw, { raw: { width, height, channels: 3 } }).png().toBuffer();
    expect(bigPng.length).toBeGreaterThan(4 * 1024 * 1024);

    mockAxiosGet.mockResolvedValue({ data: bigPng, headers: { 'content-type': 'image/png' } });
    const callLLMSpy = jest
      .spyOn(service, 'callLLM')
      .mockResolvedValue({ choices: [{ message: { content: 'a 4k cover' } }] } as any);

    const result = await service.describeImage('gemini-3.5-flash', S3_URL);

    expect(result.success).toBe(true);
    const [, messages] = callLLMSpy.mock.calls[0];
    const imgBlock = (messages[0].content as any[]).find((c: any) => c.type === 'image_url');
    expect(imgBlock.image_url.url).toMatch(/^data:image\/jpeg;base64,/);
    // The inlined, downscaled payload must be well under the original 4K size.
    const b64 = imgBlock.image_url.url.split(',')[1];
    const inlinedBytes = Buffer.from(b64, 'base64');
    expect(inlinedBytes.length).toBeLessThan(bigPng.length);
    expect(inlinedBytes.length).toBeLessThan(4 * 1024 * 1024);
  }, 20000);

  it('routes a non-S3 image URL through the SSRF-guarded fetch, never a bare axios.get', async () => {
    (isS3Url as jest.Mock).mockReturnValueOnce(false);
    const pngBytes = Buffer.from(
      'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==',
      'base64'
    );
    const externalUrl = 'https://example.com/cover.png';
    mockGuardedFetch.mockResolvedValueOnce({
      buffer: pngBytes,
      contentType: 'image/png',
      finalUrl: externalUrl,
    });
    const callLLMSpy = jest
      .spyOn(service, 'callLLM')
      .mockResolvedValue({ choices: [{ message: { content: 'ok' } }] } as any);

    const result = await service.describeImage('gemini-3.5-flash', externalUrl);

    expect(result.success).toBe(true);
    // The guarded fetch owns the request; an unguarded axios.get would be the bug.
    expect(mockGuardedFetch).toHaveBeenCalledWith(externalUrl);
    expect(mockAxiosGet).not.toHaveBeenCalled();
    // Image was still inlined for the Gemini path.
    const [, messages] = callLLMSpy.mock.calls[0];
    const imgBlock = (messages[0].content as any[]).find((c: any) => c.type === 'image_url');
    expect(imgBlock.image_url.url).toMatch(/^data:image\//);
  });

  it('follows a redirecting non-S3 URL and inlines the final image (Google Drive, ENG-834)', async () => {
    // Refusing redirects outright false-blocked ordinary one-hop image links:
    // drive.google.com/uc?export=view 303s once to drive.usercontent.google.com.
    (isS3Url as jest.Mock).mockReturnValueOnce(false);
    const webpBytes = Buffer.from('UklGRh4AAABXRUJQVlA4', 'base64');
    const driveUrl = 'https://drive.google.com/uc?export=view&id=ABC';
    mockGuardedFetch.mockResolvedValueOnce({
      buffer: webpBytes,
      contentType: 'image/webp',
      finalUrl: 'https://drive.usercontent.google.com/download?id=ABC&export=view',
    });
    const callLLMSpy = jest
      .spyOn(service, 'callLLM')
      .mockResolvedValue({ choices: [{ message: { content: 'ok' } }] } as any);

    const result = await service.describeImage('gemini-3.5-flash', driveUrl);

    expect(result.success).toBe(true);
    expect(mockGuardedFetch).toHaveBeenCalledWith(driveUrl);
    // Inlined, not handed to Gemini as a bare URL it cannot follow.
    const [, messages] = callLLMSpy.mock.calls[0];
    const imgBlock = (messages[0].content as any[]).find((c: any) => c.type === 'image_url');
    expect(imgBlock.image_url.url).toMatch(/^data:image\//);
    expect(imgBlock.image_url.url).not.toBe(driveUrl);
  });

  it('does not fetch a non-S3 URL that the SSRF guard blocks (falls back to the raw URL)', async () => {
    (isS3Url as jest.Mock).mockReturnValueOnce(false);
    mockGuardedFetch.mockRejectedValueOnce(new SsrfBlockedError());
    const callLLMSpy = jest
      .spyOn(service, 'callLLM')
      .mockResolvedValue({ choices: [{ message: { content: 'ok' } }] } as any);

    const internalUrl = 'http://169.254.169.254/latest/meta-data/';
    const result = await service.describeImage('gemini-3.5-flash', internalUrl);

    expect(result.success).toBe(true);
    // Blocked before any server-side fetch of the internal endpoint.
    expect(mockAxiosGet).not.toHaveBeenCalled();
    // No inlined bytes were produced; the raw URL is passed through unchanged.
    const [, messages] = callLLMSpy.mock.calls[0];
    const imgBlock = (messages[0].content as any[]).find((c: any) => c.type === 'image_url');
    expect(imgBlock.image_url.url).toBe(internalUrl);
  });

  /**
   * Graceful-degradation contract: routing this fetch through our own server
   * introduced a failure mode the pre-fix code did not have (the download itself
   * can fail — timeout, DNS, 404, redirect loop). Whenever that happens the
   * vision call MUST still be attempted with the original URL, exactly as it was
   * before the guard existed, so the guarded fetch can never make describe_image
   * worse than it was. These pin that contract for the non-SSRF failures; the
   * SsrfBlockedError case is covered above.
   */
  it.each([
    ['a network/timeout error', new Error('timeout of 30000ms exceeded')],
    ['an unreachable host', Object.assign(new Error('getaddrinfo ENOTFOUND img.example.com'), { code: 'ENOTFOUND' })],
    ['a 404 from the origin', new Error('Request failed with status code 404')],
    ['an exhausted redirect chain', new Error('Too many redirects (>5)')],
  ])('still attempts the vision call with the raw URL when the fetch fails with %s', async (_label, err) => {
    (isS3Url as jest.Mock).mockReturnValueOnce(false);
    mockGuardedFetch.mockRejectedValueOnce(err);
    const consoleError = jest.spyOn(console, 'error').mockImplementation(() => {});
    const callLLMSpy = jest
      .spyOn(service, 'callLLM')
      .mockResolvedValue({ choices: [{ message: { content: 'ok' } }] } as any);

    const externalUrl = 'https://img.example.com/cover.png';
    const result = await service.describeImage('gemini-3.5-flash', externalUrl);

    // Degrades to the pre-fix behaviour rather than surfacing a hard tool error.
    expect(result.success).toBe(true);
    expect(callLLMSpy).toHaveBeenCalled();
    const [, messages] = callLLMSpy.mock.calls[0];
    const imgBlock = (messages[0].content as any[]).find((c: any) => c.type === 'image_url');
    expect(imgBlock.image_url.url).toBe(externalUrl);

    consoleError.mockRestore();
  });
});
